 "content": "def transform(grid):
    """Complete a cyclic row/diagonal pattern from its nonblank entries."""
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])

    # A stack of monochromatic rows encodes a repeating vertical sequence.
    row_colors = []
    row_stack = True
    for r in g:
        if len(set(r)) == 1:
            row_colors.append(r[0])
        else:
            row_stack = False
            break
    if row_stack and any(c != 0 for c in row_colors):
        known = [(i, c) for i, c in enumerate(row_colors) if c != 0]
        for period in range(1, h + 1):
            residues = {}
            valid = True
            for i, color in known:
                k = i % period
                if k in residues and residues[k] != color:
                    valid = False
                    break
                residues[k] = color
            if valid and len(residues) == period:
                return [[residues[i % period] for _ in range(w)] for i in range(h)]

    # Otherwise infer a cyclic diagonal Latin-like pattern. For either slope,
    # all observed nonzero cells on a diagonal must have the same color.
    if h == w:
        n = h
        for slope in (1, -1):
            pattern = {}
            valid = True
            for r in range(n):
                for c in range(n):
                    color = g[r][c]
                    if color == 0:
                        continue
                    k = (c + slope * r) % n
                    if k in pattern and pattern[k] != color:
                        valid = False
                        break
                    pattern[k] = color
                if not valid:
                    break
            if valid and len(pattern) == n:
                return [[pattern[(c + slope * r) % n] for c in range(n)] for r in range(n)]

    return g


